package in.recallradar;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class ProductionPlanningTest { @Autowired ProductionService production; @Autowired InventoryService inventory; @Autowired TenantService tenants; @Autowired UserRepository users; @Autowired MembershipRepository memberships; @Autowired LocationRepository locations; @Autowired SupplierRepository suppliers; @Autowired IngredientRepository ingredients;
@Test void suggestsEarliestExpiryLotsAndCreatesBatchOnConfirmation(){var user=users.save(new AppUser("Planner","planner@test.example","hash"));var org=tenants.createWorkspace(user,"Planning Kitchens");var member=memberships.findByUserIdAndOrganizationId(user.id,org.id).orElseThrow();var location=locations.save(new Location(org.id,"Kitchen",LocationType.WAREHOUSE,"Hyderabad"));var supplier=suppliers.save(new Supplier(org.id,"Supplier",null,null,null));var ingredient=ingredients.save(new Ingredient(org.id,"Curd","Dairy","kg"));var newer=inventory.receive(member,new ReceiveLotRequest(ingredient.id,supplier.id,"NEW",null,LocalDate.of(2027,2,1),location.id,new BigDecimal("10"),"kg",null));var older=inventory.receive(member,new ReceiveLotRequest(ingredient.id,supplier.id,"OLD",null,LocalDate.of(2027,1,1),location.id,new BigDecimal("10"),"kg",null));var product=production.product(member,new ProductRequest("Curd Wrap","CW","pieces"));var recipe=production.createRecipe(member,new RecipeRequest(java.util.UUID.fromString(product.id()),"Wrap recipe",new BigDecimal("10"),"pieces",java.util.List.of(new RecipeLineRequest(ingredient.id,new BigDecimal("2"),"kg"))));var plan=production.preview(member,new ProductionPlanRequest(java.util.UUID.fromString(recipe.id()),location.id,new BigDecimal("10"),"Dinner"));assertTrue(plan.ready());assertEquals("OLD",plan.lines().get(0).lots().get(0).supplierBatchNumber());var batch=production.produceSuggested(member,new ProductionPlanRequest(java.util.UUID.fromString(recipe.id()),location.id,new BigDecimal("10"),"Dinner"));assertTrue(batch.batchNumber().startsWith("PRD-"));assertEquals("OLD",batch.consumptions().get(0).supplierBatchNumber());assertEquals(0,new BigDecimal("8").compareTo(inventory.inventory(member).stream().filter(x->x.lot().id().equals(older.lot().id())).findFirst().orElseThrow().totalQuantity()));assertEquals(0,new BigDecimal("10").compareTo(inventory.inventory(member).stream().filter(x->x.lot().id().equals(newer.lot().id())).findFirst().orElseThrow().totalQuantity()));}}
